using System.Reflection;using System.Text.Json;using System.Text;using ValveKeyValue;using ValveKeyValue.KeyValues3;using ValveResourceFormat;using ValveResourceFormat.ResourceTypes;
internal static class ParticleRecolorTests {
 public static void Run(Assembly assembly,string dir){
  void Check(bool condition,string message){if(!condition)throw new Exception(message);}
  KVObject V(params double[] values){var a=KVObject.Array();foreach(var n in values)a.Add(new KVObject(n));return a;}
  KVObject O(string cls){var o=KVObject.Collection();o["_class"]=new KVObject(cls);return o;}
  void WriteKv(string file,KVObject root){var block=new BinaryKV3(root,new KV3ID("generic",new Guid("7412167c-06e9-4698-aff2-e63eb59037e7"))){Resource=new Resource(),SerializationVersion=5};using var payload=new MemoryStream();block.Serialize(payload);using var stream=File.Create(file);using var w=new BinaryWriter(stream);w.Write((uint)(28+payload.Length));w.Write((ushort)12);w.Write((ushort)1);w.Write(8u);w.Write(1u);w.Write(System.Text.Encoding.ASCII.GetBytes("DATA"));w.Write(8u);w.Write((uint)payload.Length);w.Write(payload.ToArray());}
  var root=O("CParticleSystemDefinition");root["m_Initializers"]=KVObject.Array();var random=O("C_INIT_RandomColor");random["m_ColorMax"]=V(255,90,0,117);root["m_Initializers"].Add(random);var cp=O("C_INIT_RemapCPtoVector");cp["m_nFieldOutput"]=new KVObject(6);cp["m_nCPInput"]=new KVObject(15);cp["m_vOutputMax"]=V(1,1,1);root["m_Initializers"].Add(cp);
  root["m_Operators"]=KVObject.Array();var lerp=O("C_OP_LerpVector");lerp["m_nFieldOutput"]=new KVObject(6);lerp["m_vecOutput"]=V(1,.1,.1);root["m_Operators"].Add(lerp);var position=O("C_INIT_InitialVelocityNoise");position["m_vecOutputMax"]=V(120,120,0);root["m_Operators"].Add(position);
  root["m_Renderers"]=KVObject.Array();var renderer=O("C_OP_RenderSprites");renderer["m_flAddSelfAmount"]=new KVObject(2d);renderer["m_vecColorScale"]=KVObject.Collection();renderer["m_vecColorScale"]["m_nType"]=new KVObject("PVEC_TYPE_LITERAL_COLOR");renderer["m_vecColorScale"]["m_LiteralColor"]=V(229,54,0);renderer["m_hTexture"]=new KVObject("materials/test/color.vtex"){Flag=KVFlag.Resource};renderer["m_hNormalTexture"]=new KVObject("materials/test/normal.vtex"){Flag=KVFlag.Resource};root["m_Renderers"].Add(renderer);
  string input=Path.Combine(dir,"rgb-source.vpcf_c"),output=Path.Combine(dir,"rgb-output.vpcf_c"),texture=Path.Combine(dir,"rgb.vtex_c"),gray=Path.Combine(dir,"gray.vtex_c"),normal=Path.Combine(dir,"normal.vtex_c");WriteKv(input,root);
  using(var stream=File.Create(texture))using(var w=new BinaryWriter(stream)){w.Write(68u);w.Write((ushort)12);w.Write((ushort)1);w.Write(8u);w.Write(1u);w.Write(System.Text.Encoding.ASCII.GetBytes("DATA"));w.Write(8u);w.Write(40u);w.Write((ushort)1);w.Write((ushort)0);for(int i=0;i<4;i++)w.Write(0f);w.Write((ushort)2);w.Write((ushort)2);w.Write((ushort)1);w.Write((byte)4);w.Write((byte)1);w.Write(0u);w.Write(0u);w.Write(0u);for(int i=0;i<4;i++){w.Write((byte)255);w.Write((byte)90);w.Write((byte)0);w.Write((byte)(17+i));}}
  var manifest=Path.Combine(dir,"rgb-relocate.json");File.WriteAllText(manifest,JsonSerializer.Serialize(new{paths=new Dictionary<string,string>(),recolorParticleTextures=true,files=new object[]{new{input,output,color=new[]{0,203,10}},new{input=texture,output=gray,name="materials/test/color.vtex_c"},new{input=texture,output=normal,name="materials/test/normal.vtex_c"}}}));assembly.GetType("ResourceRelocator")!.GetMethod("Run")!.Invoke(null,new object[]{manifest});
  using(var resource=new Resource{FileName=output}){resource.Read(output);var p=((ParticleSystem)resource.DataBlock!).Data;var init=p["m_Initializers"][0];Check(init["m_ColorMin"][1].ToInt32(null)==203&&init["m_ColorMin"].Count==4,"Omitted random minimum retained default white");Check(init["m_ColorMax"][3].ToInt32(null)==117,"Particle alpha changed");Check(p["m_Renderers"][0]["m_vecColorScale"]["m_LiteralColor"][0].ToInt32(null)==0,"Renderer retained orange");Check(p["m_Renderers"][0]["m_flAddSelfAmount"].ToDouble(null)==0,"Self texture color remained enabled");Check(p["m_Operators"][0]["m_vecOutput"][0].ToDouble(null)==0,"Later operator restored red");Check(p["m_Operators"][1]["m_vecOutputMax"][0].ToDouble(null)==120,"Velocity was mistaken for color");Check(Math.Abs(p["m_Initializers"][1]["m_vOutputMin"][1].ToDouble(null)-203/255d)<1e-6,"Prismatic CP remap can override chosen color");}
  Check(File.ReadAllBytes(normal).SequenceEqual(File.ReadAllBytes(texture)),"Normal/mask texture was changed");using(var resource=new Resource{FileName=gray}){resource.Read(gray);using var bitmap=((Texture)resource.DataBlock!).GenerateBitmap();for(int i=0;i<4;i++){var c=bitmap.Pixels[i];Check(c.Red==255&&c.Green==255&&c.Blue==255&&c.Alpha==17+i,"Texture color/alpha not preserved");}}
  Console.WriteLine("Particle RGB regression passed: renderer, lerp, CP remap, defaults, alpha and color-only texture neutralization.");
 }
}
